MultiLanguageItemData['it'][12836] = {name = "[q3]Progetto: Guardiagelo", additional_info = "[q2]Usa: Ti insegna a creare una Guardiagelo.\nRichiede Forgiatura Classica (300)\nPrezzo di vendita:\n[q3]Guardiagelo\nSi vincola all'equipaggiamento\n{Una mano} {Spada}\n{3 - 7 Danni} {Velocità 2.60}\n(1.9 danni per secondo)\nIntegrità 90 / 90\n[q2]Probabilità all'impatto: Rallenta il bersaglio del 30% e aumenta l'intervallo tra gli attacchi del 25% per 5 s.\nPrezzo di vendita: \nRichiede Lingotto d'Arcanite (18), Zaffiro Blu (8), Diamante Azerotiano (8), Essenza d'Acqua (4), Pietra da Molatura Densa (2), Cuoio Incantato (4)"}
MultiLanguageItemData['it'][12837] = {name = "[q3]Progetto: Martello della Tempesta Capolavoro", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare un Martello della Tempesta Capolavoro.\nRichiede Forgiatura Classica (300)\nPrezzo di vendita:\n[q3]Martello della Tempesta Capolavoro\nSi vincola all'equipaggiamento\n{Una mano} {Mazza}\n{4 - 6 Danni} {Velocità 2.60}\n(1.9 danni per secondo)\nIntegrità 90 / 90\n[q2]Probabilità all'impatto: Travolge fino a un massimo di 3 bersagli, infliggendo 2 danni da natura.\nPrezzo di vendita: \nRichiede Lingotto di Torio Incantato (20), Smeraldo Gigante (8), Opale Gigante (8), Essenza di Terra (6), Cuoio Incantato (4)"}
