MultiLanguageItemData['it'][18241] = {name = "[q4]Briglie del Destriero da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Destriero da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo destriero è stato addestrato a sopportare combattimenti brutali nel cuore dei più selvaggi campi di battaglia.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageItemData['it'][18242] = {name = "[q4]Redini della Tigre da Guerra Nera", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Tigre da Guerra Nera cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Così come le fiere della notte, le tigri sono rinomate per i loro taglienti artigli, la loro incredibile agilità e la passione per i grattini dietro alle orecchie.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageItemData['it'][18243] = {name = "[q4]Calcaguerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Calcaguerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Uno Gnomo in battaglia su una cavalcatura sufficientemente veloce è una vista terribile e spettacolare al tempo stesso.\" - Gran Meccanista Meccatork\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageItemData['it'][18244] = {name = "[q4]Montone da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Montone da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Nani apprezzano i montoni per il coraggio con cui caricano in battaglia.\"\nMercante:\nTenente Karter\nZona:\nRoccavento\nCosto:\n15"}
MultiLanguageItemData['it'][18245] = {name = "[q4]Corno del Lupo da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Lupo da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Animali particolarmente apprezzati dalle guardie di Orgrimmar per il loro ottimo senso dell'olfatto.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageItemData['it'][18246] = {name = "[q4]Fischietto del Raptor da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Raptor da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Proviene dalla stessa stirpe di raptor a cui appartiene Ohgan, razza che ha portato spesso alla vittoria l'Impero dei Gurubashi.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageItemData['it'][18247] = {name = "[q4]Kodo da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Kodo da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il Kodo da Guerra Nero viene allevato dagli Stallieri Kor'kron per il suo carattere aggressivo e imprevedibile. Il suo barrito di battaglia annuncia sempre uno spargimento di sangue.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageItemData['it'][18248] = {name = "[q4]Cavallo da Guerra Scheletrico Rosso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Cavallo da Guerra Scheletrico Rosso cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Quando gli eroi caduti vengono fatti risorgere nella non morte, anche i loro destrieri subiscono lo stesso destino.\"\nMercante:\nIncursore Bork\nZona:\nOrgrimmar\nCosto:\n15"}
