MultiLanguageItemData['it'][35225] = {name = "[q3]Razzo Fatuo X-51", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un missile cavalcabile! La velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Originariamente progettato come propulsore per un razzo più grande, l'X-51 si è rivelato ottimale come mezzo per un singolo passeggero.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
MultiLanguageItemData['it'][35226] = {name = "[q4]Razzo Fatuo X-51 X-TREME", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un missile cavalcabile estremo! La velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ciò che gli manca in fatto di sicurezza viene compensato dalla velocità e dallo stile. Non adatto ai deboli di cuore.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
