MultiLanguageItemData['it'][43951] = {name = "[q4]Redini del Draco Bronzeo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Draco Bronzeo cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il tempo perso è perso per sempre. Oh, aspetta... l'ho appena ritrovato.\" - Cronormu\nBottino:\nCorruttore dell'Infinito\nZona:\nEpurazione di Stratholme"}
MultiLanguageItemData['it'][43952] = {name = "[q4]Redini del Draco di Zaffiro", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Draco di Zaffiro cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Parla sempre con educazione a un drago infuriato.\"\nBottino:\nDono di Alexstrasza\nZona:\nOcchio dell'Eternità"}
MultiLanguageItemData['it'][43953] = {name = "[q4]Redini del Draco Blu", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Draco Blu cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Mai mettersi tra il drago e l'oggetto della sua ira.\"\nBottino:\nDono di Alexstrasza\nZona:\nOcchio dell'Eternità"}
MultiLanguageItemData['it'][43954] = {name = "[q4]Redini del Draco del Crepuscolo", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Draco del Crepuscolo cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ricorda la regola più importante, la regola che non devi mai dimenticare: non importa quanto possa piangere o quanto possa pregarti, non dargli mai da mangiare dopo mezzanotte.\"\nBottino:\nSartharion\nZona:\nSantuario di Ossidiana"}
MultiLanguageItemData['it'][43955] = {name = "[q4]Redini del Draco Rosso", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Draco Rosso cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeLega dei Draghi\n- Osannato\n\n\n[q]\"Non credere mai alle storie dei menestrelli. Un drago non farebbe mai male a un'anima, sempre che l'anima non attacchi per prima.\"\nMercante:\nCielstrasza\nZona:\nDracombra\nFazione:\nLega dei Draghi - Osannato\nCosto:\n2."}
MultiLanguageItemData['it'][43956] = {name = "[q4]Redini del Mammut da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Mammut da Guerra Nero cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Bestie normalmente placide, queste intelligenti creature stabiliscono un forte legame con i loro cavalieri, rendendole fedeli e impavidi in battaglia.\"\nMercante:\nCavaliere Dameron\nZona:\nLungoinverno\nCosto:\n15"}
MultiLanguageItemData['it'][43958] = {name = "[q4]Redini del Mammut del Ghiaccio", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Mammut del Ghiaccio cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeFigli di Hodir\n- Riverito\nPrezzo di vendita:\n[q]\"Molti Giganti del Ghiaccio sostengono di aver addestrato i loro mammut bianchi a scatenare valanghe sfruttando i loro possenti barriti.\"\nMercante:\nLillehoff\nZona:\nCime Tempestose\nFazione:\nFigli di Hodir - Riverito\nCosto:\n1."}
MultiLanguageItemData['it'][43959] = {name = "[q4]Redini del Gran Mammut da Guerra Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura per tre passeggeri.\n[q2]Evoca e congeda un Gran Mammut da Guerra Nero cavalcabile! Permette il trasporto di due personaggi aggiuntivi appartenenti allo stesso gruppo del proprietario.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un tempo utilizzati dai Giganti per trasportare i loro guerrieri pesantemente armati, i Gran Mammut da Guerra possono facilmente trasportare più di un cavaliere di dimensioni normali.\"\nBottino:\nZona:\nVolta di Archavon"}
MultiLanguageItemData['it'][43961] = {name = "[q4]Redini del Gran Mammut del Ghiaccio", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura per tre passeggeri.\n[q2]Evoca e congeda un Gran Mammut del Ghiaccio cavalcabile! Permette il trasporto di due personaggi aggiuntivi appartenenti allo stesso gruppo del proprietario.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeFigli di Hodir\n- Osannato\nPrezzo di vendita:\n[q]\"A causa dei forti venti e delle valanghe, i Figli di Hodir raccomandano di affrontare i pericolosi sentieri delle Cime Tempestose con almeno due compagni.\"\nMercante:\nLillehoff\nZona:\nCime Tempestose\nFazione:\nFigli di Hodir - Osannato\nCosto:\n10."}
