MultiLanguageItemData['it'][45589] = {name = "[q4]Tecnostruzzo di Gnomeregan", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Tecnostruzzo di Gnomeregan cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Da usare quando devi arrivare a destinazione il prima possibile.\" - Rillie Girateste\nMercante:\nRillie Girateste\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageItemData['it'][45590] = {name = "[q4]Elekk di Exodar", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Elekk di Exodar cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"L'Elekk di Exodar è una bestia consacrata da O'ros, il Naaru che ha viaggiato da Draenor verso Azeroth con Velen e i suoi seguaci.\"\nMercante:\nIrisee\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageItemData['it'][45591] = {name = "[q4]Fiera della Notte Darnassiana", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Fiera della Notte Darnassiana cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Quando muore una cavalcatura degli Elfi della Notte, il cavaliere tiene per tradizione una delle zanne della fiera per ricordare il compagno caduto.\"\nMercante:\nRook Pugnofalco\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageItemData['it'][45592] = {name = "[q4]Kodo di Picco del Tuono", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Kodo di Picco del Tuono cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Membro alfa del branco, questo kodo è un perfetto esemplare delle possenti creature che vivono a Mulgore.\"\nMercante:\nDoru Corno Tonante\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
MultiLanguageItemData['it'][45593] = {name = "[q4]Raptor Lanciascura", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Raptor Lanciascura cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa razza di raptor, originariamente allevata dai Drakkari, viene ora comunemente usata anche dai Lanciascura a Nordania.\"\nMercante:\nSamamba\nZona:\nCorona di Ghiaccio\nCosto:\n100"}
