MultiLanguageItemData['it'][46108] = {name = "[q2]Tecnica: Rituali della Luna Nuova", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare dei Rituali della Luna Nuova.\nRichiede Runografia di Nordania (1)\nPrezzo di vendita:\n[q3]Rituali della Luna Nuova\nSi vincola all'equipaggiamento\nAccessorio\n+6 Intelletto\n+3 Tempra\n[q2]+ 2 Critico\n[q2]Usa: Trasforma in un lupo gigante. (10 Min Recupero)\nPrezzo di vendita: \nRichiede Cartapecora Leggera (10), Inchiostro del Mare (5), Ombra Eterna (3)\n Reagenti Facoltativi: [] (#49)"}
MultiLanguageItemData['it'][46109] = {name = "[q3]Tartaruga di Mare", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura, che si muove lentamente sulla terra ma è molto veloce in acqua.\n[q2]Evoca e congeda una Tartaruga di Mare cavalcabile. Questa cavalcatura è lenta sulla terra, ma molto veloce in acqua.\n\n A causa della sua natura placida e mansueta, la velocità di nuoto non è influenzata da effetti che aumentano o riducono la velocità su cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\n\n\n[q]\"Spesso catturata dai pescatori quando è ancora piccola, questa cavalcatura si trova molto più a suo agio in acqua che sulla terraferma.\"\nProfessione:\nPesca"}
