MultiLanguageItemData['it'][49282] = {name = "[q4]Grande Orso da Battaglia", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Grande Orso da Battaglia cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"È grande, è pronto alla battaglia ed è un orso. Cos'altro potresti volere da una cavalcatura?\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
MultiLanguageItemData['it'][49283] = {name = "[q3]Redini della Tigre Spettrale", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Tigre Spettrale cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"In perfetto stile Goblin, Landro Colpolungo ha ottenuto il monopolio sulla distribuzione di queste misteriose cavalcature incorporee.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
MultiLanguageItemData['it'][49284] = {name = "[q4]Redini della Tigre Spettrale Rapida", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Tigre Spettrale Rapida cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli storici asseriscono che queste creature incorporee nacquero quando, con l'esplosione di Draenor, vennero rilasciate energie che deformarono la flora e la fauna locale.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
MultiLanguageItemData['it'][49285] = {name = "[q3]Razzo Fatuo X-51", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un missile cavalcabile! La velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Originariamente progettato come propulsore per un razzo più grande, l'X-51 si è rivelato ottimale come mezzo per un singolo passeggero.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
MultiLanguageItemData['it'][49286] = {name = "[q4]Razzo Fatuo X-51 X-TREME", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un missile cavalcabile estremo! La velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ciò che gli manca in fatto di sicurezza viene compensato dalla velocità e dallo stile. Non adatto ai deboli di cuore.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
